  "dh": "תולדות השמים והארץ בהבראם ביום עשות ה'",
  "ex": "דָּבָר אַחֵר בְּהִבָּרְאָם, בְּה' בְרָאָם, שֶׁנ' בְיָהּ ה' צוּר עוֹלָמִים (ישעיהו כ\"ו), בְּב' אוֹתִיוֹת הַלָּלוּ שֶׁל הַשֵּׁם יָצַר שְׁנֵי עוֹלָמִים, וְלִמֶּדְךָ כָאן שֶׁהָעוֹלָם הַזֶּה נִבְרָא בְהֵ\"א, רֶמֶז שֶׁיָּרְדוּ לְמַטָּה לִרְאוֹת שַׁחַת כְּהֵ\"א זֹאת שֶׁסְּתוּמָה מִכָּל צְדָדִים וּפְתוּחָה לְמַטָּה לָרֶדֶת דֶּרֶךְ שָׁם:",
  "rashi": "לִמֶּדְךָ שֶׁכֻּלָּם נִבְרְאוּ בָרִאשׁוֹן. דָּבָר אַחֵר בְּהִבָּרְאָם, בְּה' בְרָאָם, שֶׁנ' בְיָהּ ה' צוּר עוֹלָמִים (ישעיהו כ\"ו), בְּב' אוֹתִיוֹת הַלָּלוּ שֶׁל הַשֵּׁם יָצַר שְׁנֵי עוֹלָמִים, וְלִמֶּדְךָ כָאן שֶׁהָעוֹלָם הַזֶּה נִבְרָא בְהֵ\"א, רֶמֶז שֶׁיָּרְדוּ לְמַטָּה לִרְאוֹת שַׁחַת כְּהֵ\"א זֹאת שֶׁסְּתוּמָה מִכָּל צְדָדִים וּפְתוּחָה לְמַטָּה לָרֶדֶת דֶּרֶךְ שָׁם:",
  "tr": "‘תולדות השמים והארץ בהבראם ביום עשות ה THESE ARE THE PRODUCTIONS OF THE HEAVEN AND OF THE EARTH WHEN THEY WERE CREATED, IN THE DAY THE LORD GOD MADE EARTH AND HEAVEN — The verse teaches you that all of them (the productions of heaven and earth) were created on the first day when God made earth and heaven. Another explanation of the word בהבראם: It may be divided as בה' בראם He created them with the letter ‘ה, as it is said, (Isaiah 26:4) כי ביה ה' צור עולמים “For in Jah, the Lord, is the rock of worlds”, which may be explained to mean (taking צור in sense of Former, Creator) “for by means of ב these two letters י ה of the Divine Name (יהוה) God formed the two worlds” (Menachot 29b), and this verse teaches that this world was created by means of the ‘ה — a suggestion that all created beings must descend to the nether world “to behold the pit” — the world being like this letter ‘ה , which is closed on all sides but open at the bottom, thus giving a way by which they must descend.",
  "tag": "A letter's work",
  "tags": [
   "A letter's work"
  ]
