  "ex": "שֵׁם דָּבָר.",
  "rashi": "שֵׁם דָּבָר. וְלִי נִרְאֶה כְּאָדָם הָאוֹמֵר לַחֲבֵרוֹ, גְּבוּל זֶה מַגִּיעַ עַד אֲשֶׁר תָּבֹא לִגְבוּל פְּלוֹנִי:",
