  "dh": "ונבלה",
  "ex": "נוּ\"ן מְשַׁמֵּשׁ בִּלְשׁוֹן רַבִּים, וְהֵ\"א אַחֲרוֹנָה יְתֵרָה, כְהֵ\"א שֶׁל נֵרְדָה:",
  "rashi": "וּנְבַלְבֵּל; נוּ\"ן מְשַׁמֵּשׁ בִּלְשׁוֹן רַבִּים, וְהֵ\"א אַחֲרוֹנָה יְתֵרָה, כְהֵ\"א שֶׁל נֵרְדָה:",
  "tr": "ונבלה means AND LET US CONFOUND The נ is the plural prefix, and the ה at the end is additional to the root as the ה in ונרדה.",
