  "dh": "יצוה",
  "ex": "לְשׁוֹן הוֹוֶה, כְמוֹ כָּכָה יַעֲשֶׂה אִיּוֹב (איוב א'):",
  "rashi": "לְשׁוֹן הוֹוֶה, כְמוֹ כָּכָה יַעֲשֶׂה אִיּוֹב (איוב א'):",
  "tr": "יצוה HE WILL COMMAND — This form of the verb (the imperfect) expresses frequentative action, as (Job 1.5) \"This Job used to do\" (יַעֲשֶׂה)",
