  "ex": "נָקוּד בַּחֲטַף פַּתָּח ה\"א שֶׁל הֲשׁוֹפֵט, לְשׁוֹן תְּמִיהָ, וְכִי מִי שֶׁהוּא שׁוֹפֵט לֹא יַעֲשֶׂה מִשְׁפַּט אֱמֶת:",
  "rashi": "נָקוּד בַּחֲטַף פַּתָּח ה\"א שֶׁל הֲשׁוֹפֵט, לְשׁוֹן תְּמִיהָ, וְכִי מִי שֶׁהוּא שׁוֹפֵט לֹא יַעֲשֶׂה מִשְׁפַּט אֱמֶת:",
  "tr": "השופט כל הארץ SHALL NOT THE JUDGE OF ALL THE EARTH [DO JUSTICE]? — The 'ה of השופט is punctuated with Chataph Patach because the words express a question: “Should not He who is Judge practice true justice”?",
