  "dh": "כי לא אוכל",
  "ex": "לְשׁוֹן יָחִיד;",
  "rashi": "לְשׁוֹן יָחִיד; מִכָּאן אַתָּה לָמֵד שֶׁהָאֶחָד הוֹפֵךְ וְהָאֶחָד מַצִּיל, שֶׁאֵין ב' מַלְאָכִים נִשְׁלָחִים לְדָבָר א':",
