  "parHe": "חיי שרה",
  "dh": "זקן ביתו",
  "ex": "לְפִי שֶׁהוּא דָּבוּק נָקוּד זְקַן:",
  "rashi": "לְפִי שֶׁהוּא דָּבוּק נָקוּד זְקַן:",
