  "tr": "ללין TO LODGE IN — the word means one night’s lodging. The word לין is a noun (of the same form as גיל ,שיר). She however said (Genesis 24:25) ללון (a verb, “to lodge” generally) meaning many nights’ lodging (Genesis Rabbah 60:6).",
