  "dh": "הוכיח",
  "ex": "בֵּרֵר וְהוֹדִיעַ, וְכֵן כָּל הוֹכָחָה שֶׁבַּמִּקְרָא בֵּרוּר דָּבָר:",
  "rashi": "בֵּרֵר וְהוֹדִיעַ, וְכֵן כָּל הוֹכָחָה שֶׁבַּמִּקְרָא בֵּרוּר דָּבָר:",
  "tr": "הכיח means selected and designated. So, too, wherever this word (the Hiphil of יכח) occurs in the Scriptures it signifies “making something clear”.",
