  "dh": "וילינו",
  "ex": "כָּל לִינָה שֶׁבַּמִּקְרָא לִינַת לַיְלָה אֶחָד:",
  "rashi": "כָּל לִינָה שֶׁבַּמִּקְרָא לִינַת לַיְלָה אֶחָד:",
