  "ex": "הֵ\"א זוֹ מְשַׁמֶּשֶׁת לְשׁוֹן תְּמִיהָ, כְּמוֹ הַבְּמַחֲנִים?",
  "rashi": "הֵ\"א זוֹ מְשַׁמֶּשֶׁת לְשׁוֹן תְּמִיהָ, כְּמוֹ הַבְּמַחֲנִים? הַשְּׁמֵנָה הִיא? הַכְּמוֹת נָבָל?",
  "tr": "הברכה אחת HAST THOU BUT ONE BLESSING? The ה in הברכה is the interrogative prefix, as in (Num. XIII. 19, 20) “whether in camps (הבמחנים)”, “whether it is fat (השמנה)\", and (2 Sam. III. 33) “Should Abner die (הכמות) as a churl dieth”?",
