  "ex": "לְבֵית בְּתוּאֵל, כָּל תֵּבָה שֶׁצְּרִיכָה לָמֶ\"ד בִּתְחִלָּתָהּ הֵטִיל לָהּ הֵ\"א בְּסוֹפָהּ (יבמות י\"ג):",
  "rashi": "לְבֵית בְּתוּאֵל, כָּל תֵּבָה שֶׁצְּרִיכָה לָמֶ\"ד בִּתְחִלָּתָהּ הֵטִיל לָהּ הֵ\"א בְּסוֹפָהּ (יבמות י\"ג):",
