  "dh": "מה נורא",
  "ex": "תַּרְגּוּם מַה דְּחִילוּ אַתְרָא הָדֵין, דְּחִילוּ שֵׁם דָּבָר הוּא, כְּמוֹ סוּכְלְתָנוּ וּכְסוּ לְמִלְבָּשׁ:",
  "rashi": "תַּרְגּוּם מַה דְּחִילוּ אַתְרָא הָדֵין, דְּחִילוּ שֵׁם דָּבָר הוּא, כְּמוֹ סוּכְלְתָנוּ וּכְסוּ לְמִלְבָּשׁ:",
  "tr": "מה נורא HOW FEARFUL — In the Targum it is translated by “How דחילו is this place!” דחילו is a noun, like סוכלתנו which is the Targum of תבונה “understanding” (Deuteronomy 32:28), and [וכסו [למלבש which is the Targum of ובגד ללבש “and raiment to put on”) (Genesis 28:20)",
