  "dh": "והאבן הזאת",
  "ex": "כָּךְ תְּפָרֵשׁ וָי\"ו זוֹ שֶׁל וְהָאֶבֶן:",
  "rashi": "כָּךְ תְּפָרֵשׁ וָי\"ו זוֹ שֶׁל וְהָאֶבֶן: אִם תַּעֲשֶׂה לִי אֶת אֵלֶּה, אֲנִי אֶעֱשֶׂה זֹאת:",
  "tr": "והאבן הזאת THEN THIS STONE — This is how you should explain the ו of והאבן: if He will do these things mentioned in Genesis 28:15 as He promised, then I, also, will do this:",
