  "parHe": "וישלח",
  "dh": "ארצה שעיר",
  "ex": "לְאֶרֶץ שֵׂעִיר כָּל תֵּבָה שֶׁצְּרִיכָה לָמֶ\"ד בִּתְּחִלָּתָהּ הֵטִיל לָהּ הַכָּתוּב הֵ\"א בְּסוֹפָהּ:",
  "rashi": "לְאֶרֶץ שֵׂעִיר כָּל תֵּבָה שֶׁצְּרִיכָה לָמֶ\"ד בִּתְּחִלָּתָהּ הֵטִיל לָהּ הַכָּתוּב הֵ\"א בְּסוֹפָהּ:",
  "tr": "ארצה שעיר means TO THE LAND OF SEIR — A word that requires a ל as prefix has a ה placed as a suffix (Yevamot 13b).",
