  "par": "Vayeshev",
  "parHe": "וישב",
  "dh": "הרה לזנונים",
  "ex": "שֵׁם דָּבָר, מְעֻבֶּרֶת כְּמוֹ אִשָּׁה הָרָה, וּכְמוֹ בָּרָה כַּחַמָּה:",
  "rashi": "שֵׁם דָּבָר, מְעֻבֶּרֶת כְּמוֹ אִשָּׁה הָרָה, וּכְמוֹ בָּרָה כַּחַמָּה:",
  "tr": "הרה לזנונים SHE IS WITH CHILD BY HARLOTRY — The word הרה is an adjective, meaning pregnant, like (Exodus 21:22) “a pregnant (הרה) woman” (where הרה can be only an adjective) and as (Song. 7:10) “Clear (ברה) as the sun” (where ברה is an adjective; Rashi perhaps quotes this example to prove also that הרה is from root הרר just as ברה is from ברר)",
