  "dh": "הכר נא",
  "ex": "אֵין נָא אֶלָּא לְשׁוֹן בַּקָּשָׁה – הַכֵּר נָא בוֹרַאֲךָ, וְאַל תְּאַבֵּד שָׁלֹשׁ נְפָשׁוֹת:",
  "rashi": "אֵין נָא אֶלָּא לְשׁוֹן בַּקָּשָׁה – הַכֵּר נָא בוֹרַאֲךָ, וְאַל תְּאַבֵּד שָׁלֹשׁ נְפָשׁוֹת:",
