  "dh": "ירה בים",
  "ex": "\"שְׁדִי בְיַמָּא\", שְׁדִי לְשׁוֹן יְרִיָּה, וְכֵן הוּא אוֹמֵר \"אוֹ יָרֹה יִיָּרֶה\" (שמות י\"ט) – אוֹ אִשְׁתְּדָאָה יִשְׁתְּדִי, וְהַתָּי\"ו מְשַׁמֵּשׁ בְּאֵלּוּ בִּמְקוֹם יִתְפַּעֵל:",
  "rashi": "\"שְׁדִי בְיַמָּא\", שְׁדִי לְשׁוֹן יְרִיָּה, וְכֵן הוּא אוֹמֵר \"אוֹ יָרֹה יִיָּרֶה\" (שמות י\"ט) – אוֹ אִשְׁתְּדָאָה יִשְׁתְּדִי, וְהַתָּי\"ו מְשַׁמֵּשׁ בְּאֵלּוּ בִּמְקוֹם יִתְפַּעֵל:",
  "tr": "ירה בים Onkelos translates this by שדי בימא: HE HATH CAST IN THE SEA. The word שדי is an expression for “casting”. And thus, also, it says, (Exodus 19:13) או ירה יירה which Onkelos renders by או אשתדאה ישתדי “or he shall certainly be thrown down” where the ת is used in both these words in place of (as marking) the Ithpael form, so that in these Targum words the root is שדי‎.",
