  "dh": "והקל מעליך",
  "ex": "כְּמוֹ \"וְהַכְבֵּד אֶת לִבּוֹ\" (שמות ח'), \"וְהַכּוֹת אֶת מוֹאָב\" (מלכים ב ג'), לְשׁוֹן הֹוֶה:",
  "rashi": "דָּבָר זֶה לְהָקֵל מֵעָלֶיךָ: והקל. כְּמוֹ \"וְהַכְבֵּד אֶת לִבּוֹ\" (שמות ח'), \"וְהַכּוֹת אֶת מוֹאָב\" (מלכים ב ג'), לְשׁוֹן הֹוֶה:",
  "tr": "והקל מעליך lit., AND TO LIGHTEN the burden FROM OFF YOU — this thing will serve to lighten it from off you. והקל — the grammatical form is similar to (Exodus 8:11) ”and to harden (והכבד) his heart”; (2 Kings 3:24) “and to smite (והכות) Moab” — both of which words are infinitives expressing present time.",
  "tag": "Tense and mood",
