  "rashi": "לְשׁוֹן נִפְעַל, יִהְיֶה נִשָּׂא בָם אֶת הַשֻּׁלְחָן:",
  "tr": "ונשא בם — The word ונשא is a passive (Niphal) form; the meaning is: THAT THE TABLE MAY BE BORNE BY THEM.",
