  "ex": "זֵרוּעַ שֵׁם דָּבָר הוּא, כְּמוֹ וְיִתְּנוּ לָנוּ מִן הַזֵּרֹעִים (דניאל א'):",
  "rashi": "זְרִיעָה שֶׁל מִינֵי זֵרְעוֹנִין; זֵרוּעַ שֵׁם דָּבָר הוּא, כְּמוֹ וְיִתְּנוּ לָנוּ מִן הַזֵּרֹעִים (דניאל א'):",
  "tr": "זרע זרוע means seed of any kind of seed-plant. The word זרוע is a noun (not a passive participle, when it would be punctuated ‎זָרוע), like (Daniel 1:12) \"and let them give us of pulse — זֵרוֹעִים\".",
