  "dh": "וינזרו מקדשי בני ישראל, אשר הם מקדשים לי ולא יחללו את שם קדשי",
  "ex": "סָרֵס הַמִּקְרָא וְדָרְשֵׁהוּ:",
  "rashi": "סָרֵס הַמִּקְרָא וְדָרְשֵׁהוּ:",
