  "dh": "שבעת ימים",
  "ex": "כָּל מָקוֹם שֶׁנֶּאֱמַר שִׁבְעַת שֵׁם דָּבָר הוּא — שָׁבוּעַ שֶׁל יָמִים, שטי\"נא בְּלַעַז, וְכֵן כָּל לְשׁוֹן שְׁמוֹנַת שֵׁשֶׁת חֲמֵשֶׁת שְׁלוֹשֶׁת:",
  "rashi": "כָּל מָקוֹם שֶׁנֶּאֱמַר שִׁבְעַת שֵׁם דָּבָר הוּא — שָׁבוּעַ שֶׁל יָמִים, שטי\"נא בְּלַעַז, וְכֵן כָּל לְשׁוֹן שְׁמוֹנַת שֵׁשֶׁת חֲמֵשֶׁת שְׁלוֹשֶׁת:",
  "tr": "שבעת ימים SEVEN DAYS — Wherever the term שבעת is used it is a noun (not a cardinal numeral), so that the words here mean a septaine of days (a period of seven days), in old French Similar is the meaning of all the expressions שמנת ,ששת ,חמשת ,שלשת.",
  "tag": "Rule for all of Scripture",
