  "parHe": "בחקתי",
  "dh": "כל ימי השמה",
  "ex": "לְשׁוֹן הֵעָשׂוֹת, וּמֵ\"ם דָּגֵשׁ בִּמְקוֹם כֵּפֶל שְׁמָמָה:",
  "rashi": "לְשׁוֹן הֵעָשׂוֹת, וּמֵ\"ם דָּגֵשׁ בִּמְקוֹם כֵּפֶל שְׁמָמָה:",
  "tr": "כל ימי השמה — The word השמה expresses the idea of something being done (passive infinitive; here Hophal); and the מ has a Dagesh in place of doubling that letter in the root שמם.",
