  "dh": "והבאתי מרך",
  "ex": "מ\"ם שֶׁל מֹרֶךְ יְסוֹד נוֹפֵל הוּא, כְּמוֹ מ\"ם שֶׁל מוֹעֵד וְשֶׁל מוֹקֵשׁ:",
  "rashi": "פַּחַד וְרֹךְ לֵבָב; מ\"ם שֶׁל מֹרֶךְ יְסוֹד נוֹפֵל הוּא, כְּמוֹ מ\"ם שֶׁל מוֹעֵד וְשֶׁל מוֹקֵשׁ:",
  "tr": "והבאתי מרך AND I WILL SEND A FAINTNESS [INTO THEIR HEART] —  מרך‎ means timidity and faint-heartedness. The מ is an essential letter of the noun, which, however, is omitted in the root; as is the case with the מ in the nouns מועד and ומוקש.",
