  "dh": "מלאה קטרת",
  "ex": "גִּימַטְרִיָּא שֶׁל קְטֹרֶת תרי\"ג מִצְוֹת, וּבִלְבַד שֶׁתַּחֲלִיף קוֹ\"ף בְּדָלֶ\"ת עַ\"יְ א\"ת ב\"ש ג\"ר ד\"ק:",
  "rashi": "גִּימַטְרִיָּא שֶׁל קְטֹרֶת תרי\"ג מִצְוֹת, וּבִלְבַד שֶׁתַּחֲלִיף קוֹ\"ף בְּדָלֶ\"ת עַ\"יְ א\"ת ב\"ש ג\"ר ד\"ק:",
  "tr": "מלאה קטרת — The total of the word קטרת according to their numerical value is 613, the number of the Biblical commandments, except that you must exchange the קו\"ף by דל\"ת, according to the “Method of Permutation” known as א׳׳ת ב\"ש ג\"ר ד\"ק (by which the first letter of the Alphabet may take the place of the last, the second that of the one before last etc.) (Numbers Rabbah 13:16).",
  "tag": "A letter's work",
