  "dh": "וטמא הכהן עד הערב",
  "ex": "סָרְסֵהוּ וְדָרְשֵׁהוּ — וְטָמֵא עַד הָעֶרֶב וְאַחַר יָבֹא אֶל הַמַּחֲנֶה:",
  "rashi": "סָרְסֵהוּ וְדָרְשֵׁהוּ — וְטָמֵא עַד הָעֶרֶב וְאַחַר יָבֹא אֶל הַמַּחֲנֶה:",
  "tr": "וטמא הכהן עד הערב [AND AFTERWARDS HE SHALL COME INTO THE CAMP] AND THE PRIEST SHALL BE UNCLEAN UNTO THE EVENING — Invert its order (that of the phrases forming this half of the verse), and then explain it: He shall be unclean until the evening and afterwards he shall come into the camp (cf Rashi Leviticus 11:32 and Note thereon).",
  "tag": "Short or inverted verse",
