  "parHe": "חקת",
  "dh": "ונשים",
  "ex": "שִׁי\"ן דְּגוּשָׁה, לְשׁוֹן שְׁמָמָה, כָּךְ יֹאמְרוּ הַמֹּשְׁלִים, \"וַנַּשִּׁים אוֹתָם עַד נֹפַח\" — הֲשִׁמּוֹנוּם עַד נֹפַח:",
  "rashi": "שִׁי\"ן דְּגוּשָׁה, לְשׁוֹן שְׁמָמָה, כָּךְ יֹאמְרוּ הַמֹּשְׁלִים, \"וַנַּשִּׁים אוֹתָם עַד נֹפַח\" — הֲשִׁמּוֹנוּם עַד נֹפַח:",
  "tr": "ונשים WE HAVE LAID WASTE — The ש has a Dagesh, for the word denotes waste (שמם). Thus say they who speak in parables: ונשים אותם עד נפח which signifies we have laid them waste as far as Nophah.",
