  "dh": "וקבתו לי",
  "ex": "אֵין זֶה לְשׁוֹן צִוּוּי כְּמוֹ וְקָבְנוֹ, אֶלָּא לְשׁוֹן עָתִיד — אוּלַי יִישַׁר בְּעֵינָיו וְתִקָּבֶנּוּ לִי מִשָּׁם, מלדי\"רש בְּלַעַז:",
  "rashi": "אֵין זֶה לְשׁוֹן צִוּוּי כְּמוֹ וְקָבְנוֹ, אֶלָּא לְשׁוֹן עָתִיד — אוּלַי יִישַׁר בְּעֵינָיו וְתִקָּבֶנּוּ לִי מִשָּׁם, מלדי\"רש בְּלַעַז:",
  "tr": "וקבתי לי — This is not a command as is וקבנו (v. 13), but it is a future tense: perhaps it will seem right in His eyes that thou shalt curse them for me from there; malderas in O. F.",
