  "parHe": "פינחס",
  "dh": "צרור",
  "ex": "כְּמוֹ זָכוֹר, שָׁמוֹר, לְשׁוֹן הוֹוֶה — עֲלֵיכֶם לְאַיֵּב אוֹתָם:",
  "rashi": "כְּמוֹ זָכוֹר, שָׁמוֹר, לְשׁוֹן הוֹוֶה — עֲלֵיכֶם לְאַיֵּב אוֹתָם:",
  "tr": "צרור — This grammatical form is similar to זכור and שמור: it expresses the idea of continuous present action — You must [constantly] show enmity toward them.",
