  "dh": "הצו",
  "ex": "הִשִּׂיאוּ אֶת יִשְׂרָאֵל לָרִיב עַל מֹשֶׁה, לְשׁוֹן הִפְעִילוּ:",
  "rashi": "הִשִּׂיאוּ אֶת יִשְׂרָאֵל לָרִיב עַל מֹשֶׁה, לְשׁוֹן הִפְעִילוּ:",
  "tr": "הצו means they persuaded Israel to strive against Moses — it is a grammatical form denoting “they caused someone to do something\".",
