  "rashi": "לְפִי שֶׁהוּא דָּבוּק, נְקוּדָה רֵי\"שׁ בַּחֲטָף, מִזְרָח שֶׁל שֶׁמֶשׁ – מְקוֹם זְרִיחַת הַשֶּׁמֶשׁ:",
  "tr": "מזרחה שמש — Because it (the word מזרחה) is in the construct state the ר is vowelled with Chataph (vocal Sheva), the meaning being, “the rising of the sun\", i.e., the place of the sun's rising.",
