  "dh": "במספר",
  "ex": "וְאֵינוֹ נָקוּד בַּמִּסְפָּר, לִמֵּד שֶׁהִיא דְבוּקָה, לוֹמַר בְּמִסְפַּר אַרְבָּעִים וְלֹא אַרְבָּעִים שְׁלֵמִים, אֶלָּא מִנְיָן שֶׁהוּא סוֹכֵם וּמַשְׁלִים לְאַרְבָּעִים וְהֵם אַרְבָּעִים חָסֵר אַחַת (שם):",
  "rashi": "וְאֵינוֹ נָקוּד בַּמִּסְפָּר, לִמֵּד שֶׁהִיא דְבוּקָה, לוֹמַר בְּמִסְפַּר אַרְבָּעִים וְלֹא אַרְבָּעִים שְׁלֵמִים, אֶלָּא מִנְיָן שֶׁהוּא סוֹכֵם וּמַשְׁלִים לְאַרְבָּעִים וְהֵם אַרְבָּעִים חָסֵר אַחַת (שם):",
  "tr": "בְּמספר BY A NUMBER — but it (the word) is not punctuated בַּמספר by the number; this shows that it is connected with the following word, to read בְּמִסְפַּר ארבעים [“he shall smite him”] … by the number of forty, (i.e. by the number leading to forty), not, however, a full forty, but a number that leads up to the full total of forty, i.e., forty less one (Makkot 22a).",
