  "parHe": "האזינו",
  "dh": "הלה' תגמלו זאת",
  "ex": "לְשׁוֹן תֵּמָהּ, וְכִי לְפָנָיו אַתֶּם מַעֲצִיבִין שֶׁיֵּשׁ בְּיָדוֹ לִפָּרַע מִכֶּם וְשֶׁהֵיטִיב לָכֶם בְּכָל הַטּוֹבוֹת?",
  "rashi": "לְשׁוֹן תֵּמָהּ, וְכִי לְפָנָיו אַתֶּם מַעֲצִיבִין שֶׁיֵּשׁ בְּיָדוֹ לִפָּרַע מִכֶּם וְשֶׁהֵיטִיב לָכֶם בְּכָל הַטּוֹבוֹת?",
  "tr": "הלה׳ תגמלו זאת DO YOU THUS REQUITE THE LORD? — This Is an expression of astonishment: Do you mean to grieve Him Who has the power to punish you, and Who has bestowed all these favours upon you?",
