  "parHe": "וזאת הברכה",
  "dh": "תכו",
  "ex": "לְשׁוֹן פֻּעֲלוּ, הֻתַּוְּכוּ לְתוֹךְ מַרְגְּלוֹתֶיךָ:",
  "rashi": "לְשׁוֹן פֻּעֲלוּ, הֻתַּוְּכוּ לְתוֹךְ מַרְגְּלוֹתֶיךָ:",
