  "parHe": "וזאת הברכה",
  "dh": "רצון",
  "ex": "נַחַת רוּחַ וּפִיּוּס, וְכֵן כָּל רָצוֹן שֶׁבַּמִּקְרָא:",
  "rashi": "נַחַת רוּחַ וּפִיּוּס, וְכֵן כָּל רָצוֹן שֶׁבַּמִּקְרָא:",
  "tr": "רצון means satisfaction and appeasement, and similar is the meaning wherever רצון occurs in scripture.",
